package com.alsafa.native4.core;
import android.content.ContentValues;import android.database.sqlite.SQLiteDatabase;import org.json.JSONObject;
/** Applies remote operations without generating a second outbox event. Deletes are explicit tombstones only. */
public final class Native4OperationApplier implements Native4SyncReceiver.Applier{
 @Override public void apply(SQLiteDatabase db,Native4SyncReceiver.RemoteOp op)throws Exception{JSONObject j=new JSONObject(op.payload);switch(op.kind){case "PRODUCT_CREATE":case "PRODUCT_UPDATE":productUpsert(db,op.recordId,j);break;case "PRODUCT_DELETE":productDelete(db,op.recordId,j);break;case "INVENTORY_ADJUSTMENT":inventory(db,op.recordId,j);break;default:throw new IllegalArgumentException("نوع عملية الاستقبال غير مدعوم بعد: "+op.kind);}}
 private static void productUpsert(SQLiteDatabase db,String id,JSONObject j){ContentValues v=new ContentValues();v.put("product_id",id);put(v,"name",j,"name");put(v,"barcode",j,"barcode");put(v,"brand",j,"brand");put(v,"reference",j,"reference");put(v,"category",j,"category");put(v,"color",j,"color");put(v,"currency",j,"currency");putDouble(v,"cost_price",j,"costPrice");putDouble(v,"sale_price",j,"salePrice");putInt(v,"quantity",j,"quantity");v.put("updated_at",j.optLong("updatedAt",System.currentTimeMillis()));v.putNull("deleted_at");db.insertWithOnConflict("products",null,v,SQLiteDatabase.CONFLICT_REPLACE);}
 private static void productDelete(SQLiteDatabase db,String id,JSONObject j){ContentValues v=new ContentValues();v.put("deleted_at",j.optLong("deletedAt",j.optLong("updatedAt",System.currentTimeMillis())));v.put("updated_at",j.optLong("updatedAt",System.currentTimeMillis()));db.update("products",v,"product_id=?",new String[]{id});}
 private static void inventory(SQLiteDatabase db,String id,JSONObject j){if(!j.has("quantity")&&!j.has("stockAfter"))throw new IllegalArgumentException("كمية المخزون مفقودة");ContentValues v=new ContentValues();v.put("quantity",j.has("stockAfter")?j.optInt("stockAfter"):j.optInt("quantity"));v.put("updated_at",j.optLong("updatedAt",System.currentTimeMillis()));db.update("products",v,"product_id=? AND deleted_at IS NULL",new String[]{id});}
 private static void put(ContentValues v,String col,JSONObject j,String key){if(j.has(key)&&!j.isNull(key))v.put(col,j.optString(key));}private static void putDouble(ContentValues v,String col,JSONObject j,String key){if(j.has(key)&&!j.isNull(key))v.put(col,j.optDouble(key));}private static void putInt(ContentValues v,String col,JSONObject j,String key){if(j.has(key)&&!j.isNull(key))v.put(col,j.optInt(key));}
}
